{
  "name": "@writingmate/auth",
  "version": "0.1.0",
  "description": "Sign in to the Writingmate API from coding agents (OpenCode, Codex) with short-lived OAuth 2.1 tokens instead of a long-lived API key.",
  "license": "MIT",
  "type": "module",
  "engines": {
    "node": ">=20.0.0"
  },
  "main": "./opencode.mjs",
  "exports": {
    ".": "./opencode.mjs",
    "./oauth": "./oauth.mjs",
    "./store": "./store.mjs"
  },
  "bin": {
    "writingmate-auth": "cli.mjs"
  },
  "files": [
    "cli.mjs",
    "oauth.mjs",
    "opencode.mjs",
    "store.mjs",
    "README.md"
  ],
  "scripts": {
    "test": "node --test *.test.mjs"
  },
  "publishConfig": {
    "access": "public"
  },
  "homepage": "https://writingmate.ai/developers",
  "keywords": [
    "writingmate",
    "opencode",
    "opencode-plugin",
    "oauth",
    "openai-compatible"
  ]
}

#!/usr/bin/env node
// writingmate-auth: sign in to the Writingmate API from a terminal.
//
//   writingmate-auth login     open the browser and sign in
//   writingmate-auth token     print a fresh access token (refreshing if needed)
//   writingmate-auth status    show whether you are signed in
//   writingmate-auth logout    forget the sign-in on this machine
//
// `token` is what other tools call: it prints only the token on stdout, so it
// can be used as Codex's `auth.command` or in `$(writingmate-auth token)`.

import { spawn } from "node:child_process";
import { createInterface } from "node:readline";
import { DEFAULT_API_BASE_URL, LoginRequiredError, startLogin } from "./oauth.mjs";
import {
  clearCredentials,
  defaultStorePath,
  getAccessToken,
  readCredentials,
  writeCredentials,
} from "./store.mjs";

const HELP = `Usage: writingmate-auth <command>

  login [--no-browser] [--base-url <url>]   Sign in with your Writingmate account
  token [--refresh]                         Print a fresh access token
  status                                    Show the current sign-in
  logout                                    Remove the sign-in from this machine
`;

function openBrowser(url) {
  // The URL comes from server metadata: only ever hand a web address to the OS.
  if (!/^https?:$/.test(new URL(url).protocol)) return;
  const [command, args] =
    process.platform === "darwin"
      ? ["open", [url]]
      : process.platform === "win32"
        ? ["rundll32", ["url.dll,FileProtocolHandler", url]]
        : ["xdg-open", [url]];
  try {
    const child = spawn(command, args, { stdio: "ignore", detached: true });
    child.on("error", () => {});
    child.unref();
  } catch {
    // No browser on this machine: the printed URL is the fallback.
  }
}

function option(args, name) {
  const index = args.indexOf(name);
  return index === -1 ? undefined : args[index + 1];
}

async function login(args) {
  const apiBaseUrl =
    option(args, "--base-url") || process.env.WRITINGMATE_API_BASE_URL || DEFAULT_API_BASE_URL;
  const attempt = await startLogin({ apiBaseUrl });

  // Everything a person reads goes to stderr; stdout stays clean for scripts.
  console.error("Sign in to Writingmate in your browser:\n");
  console.error(`  ${attempt.url}\n`);
  if (!args.includes("--no-browser")) openBrowser(attempt.url);

  let prompt;
  if (process.stdin.isTTY) {
    console.error(
      "Browser on another machine? After signing in, copy the address it lands on\n(it starts with http://127.0.0.1) and paste it here.\n",
    );
    prompt = createInterface({ input: process.stdin, output: process.stderr });
    prompt.on("line", (line) => {
      if (!line.trim()) return;
      try {
        attempt.submitRedirect(line);
      } catch (error) {
        console.error(`${error.message}\n`);
      }
    });
    prompt.on("SIGINT", () => attempt.cancel());
  }

  try {
    const credentials = await attempt.finish();
    await writeCredentials(credentials);
    console.error("Signed in. Access tokens last under an hour and refresh on their own.");
    if (process.platform === "win32") {
      // File modes do not restrict access on Windows.
      console.error(
        `Your sign-in is stored in ${defaultStorePath()}. Keep that folder private to your user account.`,
      );
    }
  } finally {
    prompt?.close();
  }
}

async function token(args) {
  process.stdout.write(`${await getAccessToken({ force: args.includes("--refresh") })}\n`);
}

async function status() {
  const credentials = await readCredentials();
  if (!credentials) {
    console.log("Not signed in. Run `writingmate-auth login`.");
    process.exitCode = 1;
    return;
  }
  const minutes = Math.max(0, Math.round((credentials.expiresAt - Date.now()) / 60_000));
  console.log(`Signed in to ${credentials.apiBaseUrl}`);
  console.log(`Access token refreshes in about ${minutes} min.`);
  console.log(`Stored in ${defaultStorePath()}`);
}

async function logout() {
  await clearCredentials();
  console.log(
    "Signed out on this machine. To end the session everywhere, remove the app in your Writingmate settings.",
  );
}

const [command, ...args] = process.argv.slice(2);
const commands = { login, token, status, logout };

if (!command || command === "--help" || command === "-h") {
  process.stderr.write(HELP);
} else if (!Object.hasOwn(commands, command)) {
  process.stderr.write(`Unknown command: ${command}\n\n${HELP}`);
  process.exitCode = 2;
} else {
  try {
    await commands[command](args);
  } catch (error) {
    console.error(error instanceof LoginRequiredError ? error.message : `Error: ${error.message}`);
    process.exitCode = 1;
  }
}
